import {OBJECTIVE_NAMES} from './macro-objectives.js';
export function objectiveDecisionMarkup(c,set){
 const {state:s,esc,img,btn}=c,p=set.pending;if(!p)return '';
 const blue=set.blue===s.myTeam,side=blue?'blue':'red',other=blue?'red':'blue',chance=n=>Math.round((blue?n:1-n)*100),skills=p.secure;
 const card=(key,ours)=>{const team=set[key],jungler=set.stats.find(x=>x.team===team&&x.role==='JGL'),tools=skills[key+'Tools'];return `<article><strong>${ours?'우리':'상대'} · ${esc(c.teamName(team))}</strong><span>${esc(p.macros[key==='blue'?0:1])}</span><p>${esc(s.players[jungler?.player]?.name??'정글러')} · 강타 지수 <b>${skills[key+'Smite'].toFixed(1)}</b></p><div class="objective-tools">${tools.length?tools.map(t=>`<span>${img(t.champion)}${esc(t.reason)}</span>`).join(''):'추가 마무리 특성 없음'}</div></article>`;};
 const trade=blue?p.tradeGold:p.redTradeGold;
 return `<section class="objective-decision" role="dialog" aria-label="오브젝트 운영 선택"><header><div><small>COACH DECISION · ${String(Math.floor(Math.round(p.minute*60)/60)).padStart(2,'0')}:${String(Math.round(p.minute*60)%60).padStart(2,'0')}</small><h2>${OBJECTIVE_NAMES[p.kind]} 앞에서 어떻게 운영할까요?</h2></div><span class="badge gold">진행 일시 정지</span></header><div class="objective-odds"><div><span>우리 교전 승률 예상</span><strong>${chance(p.fightChance)}%</strong></div><div><span>${p.kind==='grubs'?'유충 한 마리당 확보 예상':'양 팀 경합 시 확보 예상'}</span><strong>${chance(p.secureChance)}%</strong></div><div><span>포기 시 골드 교환 예상</span><strong>+${Math.round(trade)}G</strong></div></div><div class="objective-scouting">${card(side,true)}${card(other,false)}</div><p class="small muted">교전 전력·골드·성장, 정글러 강타와 마무리 스킬을 반영한 게임 추정입니다. 확보 직전 정글러 생존과 준비 상태에 따라 확률이 달라집니다. 포기하면 오브젝트를 양보하고 사이드·정글 골드를 확보합니다.</p><div class="objective-actions">${btn('싸우기 · 오브젝트 경합','objective-choice','data-choice="contest"','primary')}${btn('포기 · 골드 교환','objective-choice','data-choice="trade"','ghost')}${btn('이번 판단 자동','objective-choice','data-choice="auto"')}${btn('남은 세트 자동 진행','match-auto','','gold')}</div></section>`;
}
